package com.sharehope.donation.controller;import com.sharehope.donation.dto.*;import com.sharehope.donation.model.Donation;import com.sharehope.donation.repository.DonationRepository;import jakarta.validation.Valid;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController public class DonationController{private final DonationRepository repo;private final String secret;DonationController(DonationRepository r,@Value("${app.payment.internal-secret:}")String s){repo=r;secret=s;}
@PostMapping("/api/public/payment-events")public ResponseEntity<?> record(@RequestHeader(value="X-Payment-Secret",required=false)String supplied,@Valid @RequestBody DonationRecordRequest r){if(secret.isBlank()||!secret.equals(supplied))return ResponseEntity.status(401).build();Donation d=repo.findByProviderReference(r.providerReference()).orElseGet(()->Donation.builder().providerReference(r.providerReference()).build());d.setProvider(r.provider());d.setDonorName(r.donorName());d.setDonorEmail(r.donorEmail());d.setDonorPhone(r.donorPhone());d.setAmountCents(r.amountCents());d.setCurrency(r.currency().toUpperCase());d.setFrequency(r.frequency());d.setDesignation(r.designation());d.setStatus(r.status());return ResponseEntity.ok(repo.save(d));}
@GetMapping("/api/admin/donations")public List<Donation> list(){return repo.findAllByOrderByCreatedAtDesc();}}
